1	package com.example.starter.service;
2	
3	import java.sql.ResultSet;
4	import java.sql.SQLException;
5	import java.sql.Statement;
6	import java.sql.Timestamp;
7	import java.time.LocalDateTime;
8	import java.util.List;
9	import java.util.Optional;
10	
11	import org.springframework.jdbc.core.JdbcTemplate;
12	import org.springframework.jdbc.core.RowMapper;
13	import org.springframework.jdbc.support.GeneratedKeyHolder;
14	import org.springframework.jdbc.support.KeyHolder;
15	import org.springframework.stereotype.Component;
16	
17	import com.example.starter.support.AppClock;
18	import com.example.starter.web.NotFoundException;
19	
20	/**
21	 * 工单存储助手：工单行查询、状态流转与轨迹事件的公共实现。
22	 */
23	@Component
24	public class WorkOrderStore {
25	
26	    /** 优先级排序片段：重要等级降序、影响户数降序、接报先后升序。 */
27	    static final String PRIORITY_ORDER =
28	            " ORDER BY CASE important_level WHEN 'SPECIAL' THEN 3 WHEN 'FIRST' THEN 2"
29	            + " WHEN 'SECOND' THEN 1 ELSE 0 END DESC, affected_users DESC, outage_start_at ASC, id ASC";
30	
31	    private static final RowMapper<WorkOrderRow> ROW_MAPPER = (rs, rowNum) -> mapRow(rs);
32	
33	    private final JdbcTemplate jdbc;
34	    private final AppClock clock;
35	
36	    public WorkOrderStore(JdbcTemplate jdbc, AppClock clock) {
37	        this.jdbc = jdbc;
38	        this.clock = clock;
39	    }
40	
41	    private static WorkOrderRow mapRow(ResultSet rs) throws SQLException {
42	        long teamId = rs.getLong("team_id");
43	        Long team = rs.wasNull() ? null : teamId;
44	        Timestamp restored = rs.getTimestamp("restored_at");
45	        long mergedInto = rs.getLong("merged_into_id");
46	        Long merged = rs.wasNull() ? null : mergedInto;
47	        return new WorkOrderRow(
48	                rs.getLong("id"),
49	                rs.getString("feeder_id"),
50	                rs.getString("fault_point"),
51	                rs.getInt("affected_users"),
52	                rs.getString("important_level"),
53	                rs.getString("status"),
54	                team,
55	                rs.getTimestamp("outage_start_at").toLocalDateTime(),
56	                restored == null ? null : restored.toLocalDateTime(),
57	                merged);
58	    }
59	
60	    /**
61	     * 按ID查询工单，不存在返回空。
62	     */
63	    public Optional<WorkOrderRow> findById(long id) {
64	        List<WorkOrderRow> rows = jdbc.query(
65	                "SELECT * FROM work_order WHERE id = ?", ROW_MAPPER, id);
66	        return rows.stream().findFirst();
67	    }
68	
69	    /**
70	     * 按ID查询工单，不存在抛 404。
71	     */
72	    public WorkOrderRow requireById(long id) {
73	        return findById(id).orElseThrow(() -> new NotFoundException("工单不存在: " + id));
74	    }
75	
76	    /**
77	     * 新建工单，返回生成的工单ID。
78	     */
79	    public long insertOrder(String feederId, String faultPoint, int affectedUsers,
80	            String importantLevel, String status, LocalDateTime outageStartAt) {
81	        KeyHolder keys = new GeneratedKeyHolder();
82	        jdbc.update(con -> {
83	            var ps = con.prepareStatement(
84	                    "INSERT INTO work_order (feeder_id, fault_point, affected_users, important_level,"
85	                    + " status, outage_start_at, created_at) VALUES (?,?,?,?,?,?,?)",
86	                    Statement.RETURN_GENERATED_KEYS);
87	            ps.setString(1, feederId);
88	            ps.setString(2, faultPoint);
89	            ps.setInt(3, affectedUsers);
90	            ps.setString(4, importantLevel);
91	            ps.setString(5, status);
92	            ps.setTimestamp(6, Timestamp.valueOf(outageStartAt));
93	            ps.setTimestamp(7, Timestamp.valueOf(clock.now()));
94	            return ps;
95	        }, keys);
96	        return keys.getKey().longValue();
97	    }
98	
99	    /**
100	     * 记录工单轨迹事件。
101	     */
102	    public void addEvent(long workOrderId, String eventType, String detail) {
103	        jdbc.update(
104	                "INSERT INTO work_order_event (work_order_id, event_type, detail, created_at) VALUES (?,?,?,?)",
105	                workOrderId, eventType, detail, Timestamp.valueOf(clock.now()));
106	    }
107	
108	    /**
109	     * 查询工单轨迹事件（按时间、ID升序），格式为“类型:详情”。
110	     */
111	    public List<String> listEvents(long workOrderId) {
112	        return jdbc.query(
113	                "SELECT event_type, detail FROM work_order_event WHERE work_order_id = ?"
114	                + " ORDER BY created_at ASC, id ASC",
115	                (rs, rowNum) -> {
116	                    String detail = rs.getString("detail");
117	                    return rs.getString("event_type") + (detail == null ? "" : ":" + detail);
118	                },
119	                workOrderId);
120	    }
121	}
