29	class DispatchServiceTest extends AbstractRepairTest {
30	
31	    private static final LocalDateTime T0 = LocalDateTime.of(2026, 9, 26, 10, 0, 0);
32	
33	    @Autowired
34	    private FaultReportService reports;
