38	
39	    private long report(String requestId, String feeder, String point, int users,
40	            String importantUser, LocalDateTime at) {
41	        return reports.report(new FaultReportRequest(requestId, feeder, point, users, importantUser, at))
42	                .workOrderId();
43	    }
