45	    @Test
46	    void 派单队列按影响户数降序且同数按接报先后() {
47	        long a = report("q-1", "F02", "点A", 100, null, T0);
48	        long b = report("q-2", "F02", "点B", 300, null, T0.plusMinutes(5));
49	        long c = report("q-3", "F02", "点C", 300, null, T0.plusMinutes(1));
50	        List<QueueEntry> queue = dispatch.queue("F02");
51	        assertEquals(List.of(c, b, a), queue.stream().map(QueueEntry::workOrderId).toList());
52	    }
53	
54	    @Test
55	    void 重要用户分级优先于影响户数() {
56	        long normal = report("q-4", "F01", "点D", 500, null, T0);
57	        long special = report("q-5", "F01", "点E", 50, "市一医院", T0.plusMinutes(1));
58	        List<QueueEntry> queue = dispatch.queue("F01");
59	        assertEquals(List.of(special, normal), queue.stream().map(QueueEntry::workOrderId).toList());
60	    }
