64	        long team = teamId("抢修一班");
65	        long first = report("q-6", "F01", "点F", 100, null, T0);
66	        long second = report("q-7", "F01", "点G", 200, null, T0.plusMinutes(1));
67	        DispatchResponse r1 = dispatch.dispatch(new DispatchRequest("d-1", first, team));
68	        DispatchResponse r2 = dispatch.dispatch(new DispatchRequest("d-2", second, team));
69	        assertEquals("DISPATCHED", r1.result());
70	        assertEquals("QUEUED", r2.result());
71	        assertEquals("EXECUTING", orderStatus(first));
72	        assertEquals("QUEUED", orderStatus(second));
73	        assertEquals(1, count("work_order", "executing_team_id = ?", team));
74	    }
