76	    @Test
77	    void 并发派单同一班组仅一单执行() throws Exception {
78	        long team = teamId("抢修二班");
79	        long order1 = report("q-8", "F01", "点H", 100, null, T0);
80	        long order2 = report("q-9", "F01", "点I", 200, null, T0.plusMinutes(1));
81	        ExecutorService pool = Executors.newFixedThreadPool(2);
82	        CountDownLatch ready = new CountDownLatch(2);
83	        CountDownLatch go = new CountDownLatch(1);
84	        try {
85	            Future<DispatchResponse> f1 = pool.submit(() -> {
86	                ready.countDown();
87	                assertTrue(go.await(5, TimeUnit.SECONDS));
88	                return dispatch.dispatch(new DispatchRequest("dc-1", order1, team));
89	            });
90	            Future<DispatchResponse> f2 = pool.submit(() -> {
91	                ready.countDown();
92	                assertTrue(go.await(5, TimeUnit.SECONDS));
93	                return dispatch.dispatch(new DispatchRequest("dc-2", order2, team));
94	            });
95	            assertTrue(ready.await(5, TimeUnit.SECONDS));
96	            go.countDown();
97	            DispatchResponse r1 = f1.get(10, TimeUnit.SECONDS);
98	            DispatchResponse r2 = f2.get(10, TimeUnit.SECONDS);
99	            List<String> results = List.of(r1.result(), r2.result());
100	            assertTrue(results.contains("DISPATCHED"), "应有一单派单成功: " + results);
101	            assertTrue(results.contains("QUEUED"), "应有一单挂单等待: " + results);
102	            assertEquals(1, count("work_order", "executing_team_id = ? AND status = 'EXECUTING'", team));
103	            assertEquals(1, count("work_order", "team_id = ? AND status = 'QUEUED'", team));
104	        } finally {
105	            pool.shutdownNow();
106	        }
107	    }
108	
