package com.example.starter.service;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Component;

import com.example.starter.support.AppClock;
import com.example.starter.web.NotFoundException;

/**
 * 工单存储助手：工单行查询、状态流转与轨迹事件的公共实现。
 */
@Component
public class WorkOrderStore {

    /** 优先级排序片段：重要等级降序、影响户数降序、接报先后升序。 */
    static final String PRIORITY_ORDER =
            " ORDER BY CASE important_level WHEN 'SPECIAL' THEN 3 WHEN 'FIRST' THEN 2"
            + " WHEN 'SECOND' THEN 1 ELSE 0 END DESC, affected_users DESC, outage_start_at ASC, id ASC";

    private static final RowMapper<WorkOrderRow> ROW_MAPPER = (rs, rowNum) -> mapRow(rs);

    private final JdbcTemplate jdbc;
    private final AppClock clock;

    public WorkOrderStore(JdbcTemplate jdbc, AppClock clock) {
        this.jdbc = jdbc;
        this.clock = clock;
    }

    private static WorkOrderRow mapRow(ResultSet rs) throws SQLException {
        long teamId = rs.getLong("team_id");
        Long team = rs.wasNull() ? null : teamId;
        Timestamp restored = rs.getTimestamp("restored_at");
        long mergedInto = rs.getLong("merged_into_id");
        Long merged = rs.wasNull() ? null : mergedInto;
        return new WorkOrderRow(
                rs.getLong("id"),
                rs.getString("feeder_id"),
                rs.getString("fault_point"),
                rs.getInt("affected_users"),
                rs.getString("important_level"),
                rs.getString("status"),
                team,
                rs.getTimestamp("outage_start_at").toLocalDateTime(),
                restored == null ? null : restored.toLocalDateTime(),
                merged);
    }

    /**
     * 按ID查询工单，不存在返回空。
     */
    public Optional<WorkOrderRow> findById(long id) {
        List<WorkOrderRow> rows = jdbc.query(
                "SELECT * FROM work_order WHERE id = ?", ROW_MAPPER, id);
        return rows.stream().findFirst();
    }

    /**
     * 按ID查询工单，不存在抛 404。
     */
    public WorkOrderRow requireById(long id) {
        return findById(id).orElseThrow(() -> new NotFoundException("工单不存在: " + id));
    }

    /**
     * 新建工单，返回生成的工单ID。
     */
    public long insertOrder(String feederId, String faultPoint, int affectedUsers,
            String importantLevel, String status, LocalDateTime outageStartAt) {
        KeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement(
                    "INSERT INTO work_order (feeder_id, fault_point, affected_users, important_level,"
                    + " status, outage_start_at, created_at) VALUES (?,?,?,?,?,?,?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, feederId);
            ps.setString(2, faultPoint);
            ps.setInt(3, affectedUsers);
            ps.setString(4, importantLevel);
            ps.setString(5, status);
            ps.setTimestamp(6, Timestamp.valueOf(outageStartAt));
            ps.setTimestamp(7, Timestamp.valueOf(clock.now()));
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }

    /**
     * 记录工单轨迹事件。
     */
    public void addEvent(long workOrderId, String eventType, String detail) {
        jdbc.update(
                "INSERT INTO work_order_event (work_order_id, event_type, detail, created_at) VALUES (?,?,?,?)",
                workOrderId, eventType, detail, Timestamp.valueOf(clock.now()));
    }

    /**
     * 查询工单轨迹事件（按时间、ID升序），格式为“类型:详情”。
     */
    public List<String> listEvents(long workOrderId) {
        return jdbc.query(
                "SELECT event_type, detail FROM work_order_event WHERE work_order_id = ?"
                + " ORDER BY created_at ASC, id ASC",
                (rs, rowNum) -> {
                    String detail = rs.getString("detail");
                    return rs.getString("event_type") + (detail == null ? "" : ":" + detail);
                },
                workOrderId);
    }
}

package com.example.starter.service;

import java.sql.Statement;
import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Optional;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

import com.example.starter.support.AppClock;
import com.example.starter.support.Fingerprints;
import com.example.starter.web.ConflictException;
import com.example.starter.web.dto.FaultReportRequest;
import com.example.starter.web.dto.FaultReportResponse;

/**
 * 故障接报与研判服务：接报幂等、按“故障点+时段”去重归并、自动研判建单。
 */
@Service
public class FaultReportService {

    private final JdbcTemplate jdbc;
    private final AppClock clock;
    private final WorkOrderStore store;
    private final TransactionTemplate tx;

    public FaultReportService(JdbcTemplate jdbc, AppClock clock, WorkOrderStore store,
            PlatformTransactionManager txManager) {
        this.jdbc = jdbc;
        this.clock = clock;
        this.store = store;
        this.tx = new TransactionTemplate(txManager);
    }

    /**
     * 故障接报：同 requestId 同参返回首次结果，同键异参抛 409；同故障点同时段归并到既有工单。
     * 并发同键时由唯一约束兜底，整事务回滚后按重放/冲突重查。
     */
    public FaultReportResponse report(FaultReportRequest req) {
        LocalDateTime reportedAt = req.reportedAt() != null ? req.reportedAt() : clock.now();
        String level = resolveLevel(req.importantUser());
        String fingerprint = Fingerprints.of(req.requestId(), req.feederId(), req.faultPoint(),
                req.affectedUsers(), req.importantUser(), reportedAt);
        try {
            return tx.execute(status -> doReport(req, reportedAt, level, fingerprint));
        } catch (DuplicateKeyException e) {
            return tx.execute(status -> findReplay(req.requestId(), fingerprint)
                    .orElseThrow(() -> e));
        }
    }

    private FaultReportResponse doReport(FaultReportRequest req, LocalDateTime reportedAt,
            String level, String fingerprint) {
        Optional<FaultReportResponse> replay = findReplay(req.requestId(), fingerprint);
        if (replay.isPresent()) {
            return replay.get();
        }

        String dedupKey = req.faultPoint() + "|" + reportedAt.truncatedTo(ChronoUnit.HOURS);
        Optional<long[]> prior = findOpenReport(dedupKey);
        long reportId;
        long workOrderId;
        boolean merged;
        if (prior.isPresent()) {
            // 重复接报：归并到首报工单，累计影响用户数
            workOrderId = prior.get()[1];
            merged = true;
            jdbc.update("UPDATE work_order SET affected_users = affected_users + ? WHERE id = ?",
                    req.affectedUsers(), workOrderId);
            store.addEvent(workOrderId, "REPORTED",
                    "归并接报, 新增影响用户" + req.affectedUsers() + "户");
            reportId = insertReport(req, fingerprint, level, reportedAt, dedupKey, prior.get()[0], workOrderId);
        } else {
            // 首报：研判建单
            workOrderId = store.insertOrder(req.feederId(), req.faultPoint(), req.affectedUsers(),
                    level, "PENDING", reportedAt);
            merged = false;
            store.addEvent(workOrderId, "REPORTED", "首次接报, 故障点=" + req.faultPoint());
            store.addEvent(workOrderId, "ASSESSED", "研判完成, 重要等级=" + level + ", 影响用户" + req.affectedUsers() + "户");
            reportId = insertReport(req, fingerprint, level, reportedAt, dedupKey, null, workOrderId);
        }
        String status = store.requireById(workOrderId).status();
        return new FaultReportResponse(reportId, workOrderId, status, merged, false, reportedAt);
    }

    private Optional<FaultReportResponse> findReplay(String requestId, String fingerprint) {
        List<Object[]> rows = jdbc.query(
                "SELECT id, fingerprint, work_order_id, merged_into_id, reported_at FROM fault_report"
                + " WHERE request_id = ?",
                (rs, rowNum) -> new Object[] {
                        rs.getLong(1), rs.getString(2), rs.getLong(3),
                        rs.getObject(4), rs.getTimestamp(5).toLocalDateTime()},
                requestId);
        if (rows.isEmpty()) {
            return Optional.empty();
        }
        Object[] row = rows.get(0);
        if (!row[1].equals(fingerprint)) {
            throw new ConflictException("同键异参幂等冲突: requestId=" + requestId);
        }
        long workOrderId = (Long) row[2];
        String status = store.requireById(workOrderId).status();
        return Optional.of(new FaultReportResponse((Long) row[0], workOrderId, status,
                row[3] != null, true, (LocalDateTime) row[4]));
    }

    /**
     * 查询同时段同故障点且工单未终结（未复电、未封存、未合并）的首报，返回 [首报ID, 工单ID]。
     */
    private Optional<long[]> findOpenReport(String dedupKey) {
        List<long[]> rows = jdbc.query(
                "SELECT r.id, r.work_order_id FROM fault_report r JOIN work_order w ON r.work_order_id = w.id"
                + " WHERE r.dedup_key = ? AND r.merged_into_id IS NULL"
                + " AND w.status IN ('PENDING','QUEUED','EXECUTING') ORDER BY r.id ASC",
                (rs, rowNum) -> new long[] {rs.getLong(1), rs.getLong(2)},
                dedupKey);
        return rows.stream().findFirst();
    }

    private long insertReport(FaultReportRequest req, String fingerprint, String level,
            LocalDateTime reportedAt, String dedupKey, Long mergedIntoId, long workOrderId) {
        KeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement(
                    "INSERT INTO fault_report (request_id, fingerprint, feeder_id, fault_point,"
                    + " affected_users, important_level, reported_at, dedup_key, merged_into_id, work_order_id)"
                    + " VALUES (?,?,?,?,?,?,?,?,?,?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, req.requestId());
            ps.setString(2, fingerprint);
            ps.setString(3, req.feederId());
            ps.setString(4, req.faultPoint());
            ps.setInt(5, req.affectedUsers());
            ps.setString(6, level);
            ps.setTimestamp(7, Timestamp.valueOf(reportedAt));
            ps.setString(8, dedupKey);
            if (mergedIntoId == null) {
                ps.setObject(9, null);
            } else {
                ps.setLong(9, mergedIntoId);
            }
            ps.setLong(10, workOrderId);
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }

    /**
     * 按重要用户名称解析分级，未登记或为空返回 NONE。
     */
    private String resolveLevel(String importantUser) {
        if (importantUser == null || importantUser.isBlank()) {
            return "NONE";
        }
        List<String> levels = jdbc.query(
                "SELECT level FROM important_user WHERE user_name = ?",
                (rs, rowNum) -> rs.getString(1), importantUser);
        return levels.isEmpty() ? "NONE" : levels.get(0);
    }
}

package com.example.starter.service;

import java.sql.Timestamp;
import java.util.List;
import java.util.Optional;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

import com.example.starter.support.AppClock;
import com.example.starter.support.Fingerprints;
import com.example.starter.web.ConflictException;
import com.example.starter.web.NotFoundException;
import com.example.starter.web.dto.DispatchRequest;
import com.example.starter.web.dto.DispatchResponse;
import com.example.starter.web.dto.QueueEntry;

/**
 * 派单服务：派单幂等、班组同时刻唯一执行单、资源冲突时挂单等待、派单队列复算。
 */
@Service
public class DispatchService {

    private final JdbcTemplate jdbc;
    private final AppClock clock;
    private final WorkOrderStore store;
    private final EscalationService escalation;
    private final TransactionTemplate tx;

    public DispatchService(JdbcTemplate jdbc, AppClock clock, WorkOrderStore store,
            EscalationService escalation, PlatformTransactionManager txManager) {
        this.jdbc = jdbc;
        this.clock = clock;
        this.store = store;
        this.escalation = escalation;
        this.tx = new TransactionTemplate(txManager);
    }

    /**
     * 派单：同 requestId 同参返回首次结果，同键异参抛 409；
     * 班组空闲则执行中，否则挂单等待。班组行锁保证同时刻唯一执行单。
     */
    public DispatchResponse dispatch(DispatchRequest req) {
        String fingerprint = Fingerprints.of(req.requestId(), req.workOrderId(), req.teamId());
        try {
            return tx.execute(status -> doDispatch(req, fingerprint));
        } catch (DuplicateKeyException e) {
            return tx.execute(status -> findReplay(req.requestId(), fingerprint)
                    .orElseThrow(() -> e));
        }
    }

    private DispatchResponse doDispatch(DispatchRequest req, String fingerprint) {
        Optional<DispatchResponse> replay = findReplay(req.requestId(), fingerprint);
        if (replay.isPresent()) {
            return replay.get();
        }
        lockTeam(req.teamId());
        WorkOrderRow order = store.requireById(req.workOrderId());
        if (!"PENDING".equals(order.status()) && !"QUEUED".equals(order.status())) {
            throw new ConflictException("工单状态不可派单: " + order.status());
        }
        int executing = countExecuting(req.teamId());
        String result;
        if (executing == 0) {
            jdbc.update("UPDATE work_order SET status = 'EXECUTING', team_id = ?, executing_team_id = ?"
                    + " WHERE id = ?", req.teamId(), req.teamId(), req.workOrderId());
            store.addEvent(req.workOrderId(), "DISPATCHED", "派单至班组" + req.teamId());
            result = "DISPATCHED";
        } else {
            jdbc.update("UPDATE work_order SET status = 'QUEUED', team_id = ? WHERE id = ?",
                    req.teamId(), req.workOrderId());
            store.addEvent(req.workOrderId(), "QUEUED", "班组" + req.teamId() + "资源冲突, 挂单等待");
            result = "QUEUED";
        }
        jdbc.update("INSERT INTO dispatch_record (request_id, fingerprint, work_order_id, team_id, result, created_at)"
                + " VALUES (?,?,?,?,?,?)",
                req.requestId(), fingerprint, req.workOrderId(), req.teamId(), result,
                Timestamp.valueOf(clock.now()));
        escalation.evaluate(req.workOrderId());
        return new DispatchResponse(req.workOrderId(), req.teamId(), result,
                "DISPATCHED".equals(result) ? "EXECUTING" : "QUEUED", false);
    }

    private Optional<DispatchResponse> findReplay(String requestId, String fingerprint) {
        List<Object[]> rows = jdbc.query(
                "SELECT fingerprint, work_order_id, team_id, result FROM dispatch_record WHERE request_id = ?",
                (rs, rowNum) -> new Object[] {rs.getString(1), rs.getLong(2), rs.getLong(3), rs.getString(4)},
                requestId);
        if (rows.isEmpty()) {
            return Optional.empty();
        }
        Object[] row = rows.get(0);
        if (!row[0].equals(fingerprint)) {
            throw new ConflictException("同键异参幂等冲突: requestId=" + requestId);
        }
        String result = (String) row[3];
        return Optional.of(new DispatchResponse((Long) row[1], (Long) row[2], result,
                "DISPATCHED".equals(result) ? "EXECUTING" : "QUEUED", true));
    }

    /**
     * 锁定班组行并校验存在性；同事务内后续派单判断以此串行化。
     */
    private void lockTeam(long teamId) {
        List<Long> rows = jdbc.query("SELECT id FROM repair_team WHERE id = ? FOR UPDATE",
                (rs, rowNum) -> rs.getLong(1), teamId);
        if (rows.isEmpty()) {
            throw new NotFoundException("班组不存在: " + teamId);
        }
    }

    private int countExecuting(long teamId) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM work_order WHERE executing_team_id = ? AND status = 'EXECUTING'",
                Integer.class, teamId);
        return count == null ? 0 : count;
    }

    /**
     * 复算派单队列：待派单与挂单工单按重要等级、影响户数降序、接报先后排序；feederId 为空时查全部。
     */
    public List<QueueEntry> queue(String feederId) {
        String sql = "SELECT id, feeder_id, important_level, affected_users, outage_start_at, status"
                + " FROM work_order WHERE status IN ('PENDING','QUEUED')"
                + (feederId == null ? "" : " AND feeder_id = ?")
                + WorkOrderStore.PRIORITY_ORDER;
        var mapper = (org.springframework.jdbc.core.RowMapper<QueueEntry>) (rs, rowNum) -> new QueueEntry(
                rs.getLong("id"), rs.getString("feeder_id"), rs.getString("important_level"),
                rs.getInt("affected_users"), rs.getTimestamp("outage_start_at").toLocalDateTime(),
                rs.getString("status"));
        return feederId == null ? jdbc.query(sql, mapper) : jdbc.query(sql, mapper, feederId);
    }
}

