    @Test
    void 超时整体改派保留到场车并原子切换() {
        freezeAt(T0);
        long order = orderOnF01("gd-r-11", "组合点J");
        long ta = truck("gd-t-16", "GD-H1", 600, "F01");
        long tb = truck("gd-t-17", "GD-H2", 600, "F01");
