                try {
                    return generator.reassign(created.dispatchId(), new ReassignRequest("gd-27", 3L, List.of(tc)));
                } catch (ConflictException | UnprocessableException e) {
                    return e;
                }
            });
            Future<Object> f2 = pool.submit(() -> {
                ready.countDown();
                assertTrue(go.await(5, TimeUnit.SECONDS));
