            assertEquals(newDispatch.dispatchId(), jdbc.queryForObject(
                    "SELECT id FROM generator_dispatch WHERE predecessor_id = ?", Long.class,
                    created.dispatchId()));
        } finally {
            pool.shutdownNow();
        }
    }
